steps.solution:
import csv
present = {}
with open("register.csv") as f:
    for row in csv.DictReader(f):
        if row["status"] == "P":
            c = row["class"]
            present[c] = present.get(c, 0) + 1
for c in sorted(present):
    print(c, present[c])

