CREATE TABLE rules (kind TEXT PRIMARY KEY, keep_years INTEGER);
INSERT INTO rules VALUES ('register', 5), ('test paper', 1), ('sports photo', 1), ('final results', 50);
CREATE TABLE records (id INTEGER PRIMARY KEY, kind TEXT, year INTEGER);
INSERT INTO records VALUES (1, 'register', 2018), (2, 'register', 2023), (3, 'test paper', 2024), (4, 'test paper', 2025),
  (5, 'sports photo', 2023), (6, 'final results', 1998), (7, 'register', 2020), (8, 'sports photo', 2025);

steps.solution:
SELECT records.id, records.kind FROM records
JOIN rules ON rules.kind = records.kind
WHERE records.year + rules.keep_years < 2026;

